from pathlib import Path
import json,html,hashlib
r=Path(__file__).resolve().parents[1];d=r/'docs';rows=[];records=[]
for n in [1,2]:
 for prefix,label in [('baseline','119 páginas e catálogo'),('validation','64 componentes oficiais'),('acceptance','Interações e autoria simulada'),('v3','Contratos e integrações dos componentes'),('v3-content','Novas instâncias, temas e exemplos'),('layout','Layouts e edição de colunas')]:
  path=d/f'{prefix}-baseline-final-{n}.json';tests=json.loads(path.read_text())['tests'];passed=sum(bool(t['pass'])for t in tests)
  if passed!=len(tests):raise RuntimeError(f'Testes reprovados em {path.name}')
  records.append({'round':n,'suite':label,'passed':passed,'total':len(tests),'evidence':path.name});rows.append(f'<tr><td>{n}</td><td>{label}</td><td>{passed}/{len(tests)}</td><td><a href="{path.name}">JSON</a></td></tr>')
for file,key in [('baseline-package-validation.json','tests'),('package-audit.json','checks')]:
 if not all(x['pass']for x in json.loads((d/file).read_text())[key]):raise RuntimeError('Falha: '+file)
models=json.loads((r/'component-models.json').read_text());pages=json.loads((r/'content/pages.json').read_text());total=sum(x['total']for x in records);package=r/'content/demo-to-content.zip';sha=hashlib.sha256(package.read_bytes()).hexdigest()
summary={'version':'3.1.1','reference':'@interco/inter-toranja 1.13.3','officialComponents':64,'customCatalogBlocks':4,'classifiedOwnProperties':751,'models':len(models),'modelFields':sum(len(m['fields'])for m in models),'pages':len(pages),'assets':11,'browserChecks':total,'rounds':records,'contentPackageSHA256':sha,'remoteAEMInstallationTested':False,'remoteUEPersistenceTested':False};(d/'final-summary.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2))
